<?php echo "=== All roles in DB ===" . PHP_EOL; foreach (DB::table("roles")->get() as $r) { echo $r->id . ": " . $r->name . PHP_EOL; } echo PHP_EOL . "=== finance role permissions ===" . PHP_EOL; $rows = DB::table("role_permissions")->join("roles", "roles.id", "=", "role_permissions.role_id")->join("permissions", "permissions.id", "=", "role_permissions.permission_id")->where("roles.name", "finance")->select("permissions.module_key as module", "permissions.action_key as action", "role_permissions.allowed")->get(); foreach ($rows as $r) { echo $r->module . ":" . $r->action . " allowed=" . $r->allowed . PHP_EOL; } echo PHP_EOL . "=== user_roles for finance@sns.com ===" . PHP_EOL; $u = App\Models\User::where("email", "finance@sns.com")->first(); foreach (DB::table("user_roles")->where("user_id", $u->id)->get() as $r) { echo "role_id=" . $r->role_id . PHP_EOL; }
